import ast
import sys
import subprocess
from typing import Optional, List, Dict, Tuple
import openai  # pip install openai

class SuperCorretor:
    def __init__(self, arquivo: str):
        self.arquivo = arquivo
        self.codigo = self._carregar_codigo()
        self.erros: List[Dict] = []
        self.correcoes: List[str] = []

    def _carregar_codigo(self) -> Optional[str]:
        try:
            with open(self.arquivo, 'r', encoding='utf-8') as f:
                return f.read()
        except Exception as e:
            self._registrar_erro("IO", f"Falha ao ler arquivo: {str(e)}")
            return None

    def _registrar_erro(self, tipo: str, msg: str, linha: Optional[int] = None):
        self.erros.append({"tipo": tipo, "mensagem": msg, "linha": linha})

    def _analisar_ast(self) -> bool:
        try:
            ast.parse(self.codigo)
            return True
        except SyntaxError as e:
            self._registrar_erro("Sintaxe", f"Erro: {e.msg}", e.lineno)

            # Tentativa de correção automática
            correcao = self._corrigir_sintaxe(e)
            if correcao:
                self.correcoes.append(f"🔧 Correção aplicada na linha {e.lineno}: {correcao}")
            return False

    def _corrigir_sintaxe(self, erro: SyntaxError) -> Optional[str]:
        """Tenta corrigir erros comuns de sintaxe"""
        # Exemplo: corrige 'print x' para 'print(x)'
        if "Missing parentheses" in str(erro):
            linha_erro = erro.text.strip()
            return linha_erro.replace("print ", "print(") + ")"
        return None

    def _sugerir_refatoracao(self):
        """Analisa padrões para refatoração"""
        # Exemplo: detecta funções longas (>30 linhas)
        tree = ast.parse(self.codigo)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                linhas = node.end_lineno - node.lineno if node.end_lineno else 0
                if linhas > 30:
                    self.correcoes.append(
                        f"📏 Função '{node.name}' muito longa ({linhas} linhas). "
                        "Sugestão: Quebrar em funções menores usando Strategy Pattern."
                    )

    def _consultar_gpt(self, erro: Dict) -> str:
        """Obtém explicações detalhadas do GPT"""
        prompt = f"Explique o erro '{erro['mensagem']}' na linha {erro['linha']} em Python como um engenheiro sênior"
        try:
            resposta = openai.ChatCompletion.create(
                model="gpt-4",
                messages=[{"role": "user", "content": prompt}]
            )
            return resposta.choices[0].message.content
        except:
            return "⚠️ Falha ao consultar GPT-4"

    def executar(self) -> Dict:
        if not self.codigo:
            return {"status": "Falha", "erros": self.erros}

        sintaxe_ok = self._analisar_ast()
        if sintaxe_ok:
            self._sugerir_refatoracao()
            return {
                "status": "Sucesso",
                "correcoes": self.correcoes,
                "aviso": "✅ Sem erros de sintaxe!"
            }
        else:
            # Adiciona explicações GPT para cada erro
            for erro in self.erros:
                if erro["tipo"] == "Sintaxe":
                    erro["explicacao"] = self._consultar_gpt(erro)

            return {
                "status": "Corrigido",
                "erros": self.erros,
                "correcoes": self.correcoes
            }

if __name__ == "__main__":
