import sqlite3

class NomesDatabase:
    def __init__(self):
        self.conn = sqlite3.connect('nomes.db')
        self.criar_tabela()

    def criar_tabela(self):
        self.conn.execute('''CREATE TABLE IF NOT EXISTS nomes
                          (id INTEGER PRIMARY KEY AUTOINCREMENT,
                          nome TEXT NOT NULL UNIQUE,
                          data_cadastro TIMESTAMP DEFAULT CURRENT_TIMESTAMP)''')

    def adicionar(self, nome):
        try:
            self.conn.execute("INSERT INTO nomes (nome) VALUES (?)", (nome,))
            self.conn.commit()
        except sqlite3.IntegrityError:
            print(f"⚠️ {nome} já existe no banco!")

    def buscar(self, termo):
        cursor = self.conn.execute("SELECT nome FROM nomes WHERE nome LIKE ?", 
                                 (f'%{termo}%',))
        return [row[0] for row in cursor]

# Uso:
