class AutoCompleter:
    def __init__(self, nomes):
        self.trie = {}
        for nome in nomes:
            self._adicionar_na_trie(nome.lower())

    def _adicionar_na_trie(self, nome):
        node = self.trie
        for char in nome:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['*'] = True  # Marca fim da palavra

    def sugerir(self, prefixo):
        node = self.trie
        for char in prefixo.lower():
            if char not in node:
                return []
            node = node[char]
        return self._coletar_palavras(node, prefixo)

    def _coletar_palavras(self, node, prefixo):
        sugestoes = []
        for char, child_node in node.items():
            if char == '*':
                sugestoes.append(prefixo)
            else:
                sugestoes.extend(self._coletar_palavras(child_node, prefixo + char))
        return sugestoes

# Uso:
autocompleter = AutoCompleter(["Marllon", "João", "Maria"])
print(autocompleter.sugerir("Ma"))  # ['Marllon', 'Maria']
