def adicionar_nome(nome: NomeModel):
    nomes.append(nome.nome)
    return {"message": f"Nome {nome.nome} adicionado!"}

@app.get("/nomes")
def listar_nomes():
    return {"nomes": nomes}

@app.get("/nomes/buscar")
def buscar_nomes(termo: str):
    return {"resultados": [n for n in nomes if termo.lower() in n.lower()]}
